import{_ as a,c as i,o as t,a9 as r}from"./chunks/framework.Bqk8xQPS.js";const h=JSON.parse('{"title":"Delivery Semantics and Reliability","description":"How to design stable PURISTA systems with realistic broker guarantees","frontmatter":{"title":"Delivery Semantics and Reliability","description":"How to design stable PURISTA systems with realistic broker guarantees","order":209920},"headers":[],"relativePath":"handbook/2_building_business-logic/advanced/delivery-semantics-and-reliability.md","filePath":"handbook/2_building_business-logic/advanced/delivery-semantics-and-reliability.md","lastUpdated":1775115072000}'),d={name:"handbook/2_building_business-logic/advanced/delivery-semantics-and-reliability.md"};function n(o,e,l,s,c,m){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="delivery-semantics-and-reliability" tabindex="-1">Delivery semantics and reliability <a class="header-anchor" href="#delivery-semantics-and-reliability" aria-label="Permalink to “Delivery semantics and reliability”">​</a></h1><h2 id="guarantee-model" tabindex="-1">Guarantee model <a class="header-anchor" href="#guarantee-model" aria-label="Permalink to “Guarantee model”">​</a></h2><p>End-to-end message delivery guarantees are a combination of:</p><ol><li>the selected PURISTA event bridge</li><li>broker/component configuration</li><li>your handler design (idempotency, retries, side effects)</li></ol><h2 id="common-modes" tabindex="-1">Common modes <a class="header-anchor" href="#common-modes" aria-label="Permalink to “Common modes”">​</a></h2><ul><li><code>at-most-once</code>: lower overhead, messages can be lost</li><li><code>at-least-once</code>: safer delivery, duplicates are expected</li><li><code>exactly-once</code>: rarely guaranteed end-to-end across distributed side effects</li></ul><h2 id="design-rules-for-production" tabindex="-1">Design rules for production <a class="header-anchor" href="#design-rules-for-production" aria-label="Permalink to “Design rules for production”">​</a></h2><ul><li>make command/subscription side effects idempotent</li><li>use deterministic business keys for deduplication</li><li>avoid non-atomic “read/modify/write” side effects without protection</li><li>set timeout and retry budgets intentionally</li><li>persist important business state outside process memory</li></ul><h2 id="safe-defaults" tabindex="-1">Safe defaults <a class="header-anchor" href="#safe-defaults" aria-label="Permalink to “Safe defaults”">​</a></h2><p>PURISTA now defaults to strict startup validation for reliability-sensitive command and subscription semantics.</p><ul><li>if a handler requests delivery behavior a bridge cannot honor, startup fails in strict mode</li><li>late command responses after timeout are ignored with warning where applicable</li><li>stream sessions use bounded timeout handling and terminal-frame enforcement instead of open-ended waits</li><li>queue workers apply bounded retries and dead-letter routing using lifecycle defaults unless you override them</li></ul><h3 id="canonical-defaults-table" tabindex="-1">Canonical defaults table <a class="header-anchor" href="#canonical-defaults-table" aria-label="Permalink to “Canonical defaults table”">​</a></h3><table tabindex="0"><thead><tr><th>area</th><th>default</th><th>behavior</th></tr></thead><tbody><tr><td>command invocation timeout</td><td>bridge <code>defaultCommandTimeout</code> (30s unless configured)</td><td>caller timeout is terminal; late responses are ignored with warning</td></tr><tr><td>stream invocation timeout</td><td>bridge <code>defaultCommandTimeout</code> (unless stream timeout override is configured)</td><td>late frames after timeout/terminal are ignored with warning</td></tr><tr><td>subscription failure handling</td><td><code>mode: &#39;strict&#39;</code>, <code>maxAttempts: 1</code>, <code>retryDelayMs: 0</code> when configured without overrides</td><td>startup rejects unsupported semantics; exhausted attempts dead-letter when configured</td></tr><tr><td>queue lifecycle retry</td><td><code>maxAttempts: 10</code>, exponential retry strategy, <code>retryWindowMs: 24h</code></td><td>retries stay bounded and route to DLQ after budget/window exhaustion</td></tr></tbody></table><h2 id="drain-observability" tabindex="-1">Drain observability <a class="header-anchor" href="#drain-observability" aria-label="Permalink to “Drain observability”">​</a></h2><p>Event bridges expose in-flight diagnostics by work kind (<code>command</code>, <code>subscription</code>, <code>stream</code>, <code>generic</code>). Services can use this during shutdown and operator diagnostics to verify that drain reached zero before teardown.</p><h2 id="streams-and-reliability" tabindex="-1">Streams and reliability <a class="header-anchor" href="#streams-and-reliability" aria-label="Permalink to “Streams and reliability”">​</a></h2><p>Current stream runtime support is available in <code>DefaultEventBridge</code> only.</p><p>For stream consumers:</p><ul><li>handle terminal frames (<code>complete</code>, <code>error</code>, <code>cancel</code>) explicitly</li><li>treat cancellation as a normal control path</li><li>validate chunk/final payloads where needed</li><li>keep chunk processing resilient to partial interruptions</li><li>expect exactly one terminal state (<code>complete</code>, <code>error</code>, or <code>cancel</code>) per session</li></ul><h2 id="minimal-acceptance-checklist" tabindex="-1">Minimal acceptance checklist <a class="header-anchor" href="#minimal-acceptance-checklist" aria-label="Permalink to “Minimal acceptance checklist”">​</a></h2><ul><li>broker-level delivery mode is documented for each environment</li><li>duplicate-handling strategy is tested</li><li>retry policy is tested against transient failures</li><li>operational runbook includes outage and reconnect behavior</li></ul>',21)])])}const b=a(d,[["render",n]]);export{h as __pageData,b as default};
